"use strict";

// ── Config ──────────────────────────────────────────────────────────────────
// config.js is generated by Terraform and defines window.APP_CONFIG.
const API_URL = (window.APP_CONFIG && window.APP_CONFIG.apiUrl || "").replace(/\/+$/, "");
const THRESHOLD = 4;
const POLL_INTERVAL_MS = 4000;
const POLL_TIMEOUT_MS = 6 * 60 * 1000;

const ANALYST_NAMES = {
  2: ["Sarah (Network)", "Marc (Phishing)"],
  3: ["Sarah (Network)", "Marc (Phishing)", "David (Forensics)"],
  4: ["Sarah (Network)", "Marc (Phishing)", "David (Forensics)", "Lisa (Malware)"],
  5: ["Sarah (Network)", "Marc (Phishing)", "David (Forensics)", "Lisa (Malware)", "Chen (Cloud)"],
};
const ALERT_NAMES = {
  2: ["Ransomware", "Data Exfiltration"],
  3: ["Ransomware", "Data Exfiltration", "Phishing Campaign"],
  4: ["Ransomware", "Data Exfiltration", "Phishing Campaign", "SQL Injection"],
  5: ["Ransomware", "Data Exfiltration", "Phishing Campaign", "SQL Injection", "DDoS Attack"],
};

let pollTimer = null;

// ── Helpers ─────────────────────────────────────────────────────────────────
const $ = (id) => document.getElementById(id);

// Every value that comes from the API or user input goes through escapeHtml
// before it touches innerHTML.
function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function getN() { return parseInt($("size-select").value, 10); }

function factorial(n) {
  let r = 1;
  for (let i = 2; i <= n; i++) r *= i;
  return r;
}

function formatUSD(val) {
  const num = Number(val);
  return Number.isFinite(num) ? "$" + num.toLocaleString("en-US") : "—";
}

function formatPct(val, digits = 1) {
  const num = Number(val);
  return Number.isFinite(num) ? (num * 100).toFixed(digits) + "%" : "—";
}

function randCost() {
  return Math.round(Math.random() * 110 + 10) * 1000;
}

// ── Layout ──────────────────────────────────────────────────────────────────
function onSizeChange() {
  const n = getN();
  buildTable(n);
  updateModeBadge(n);
  updateChips(n);
  resetResult();
}

function updateModeBadge(n) {
  const badge = $("mode-badge");
  const label = $("mode-label");
  const info  = $("info-bar");
  const btn   = $("btn-submit");
  const fact  = factorial(n).toLocaleString("en-US");
  const sep   = '<span class="info-sep">·</span>';

  if (n <= THRESHOLD) {
    badge.className   = "mode-badge classical";
    label.textContent = "Classical Brute-Force";
    btn.className     = "classical";
    info.className    = "info-bar";
    info.innerHTML    = `N = <span>${n}</span> ${sep} Evaluates <span>${fact}</span> combinations ${sep} Exact global optimum ${sep} Synchronous result`;
  } else {
    badge.className   = "mode-badge quantum";
    label.textContent = "Quantum QAOA";
    btn.className     = "quantum";
    info.className    = "info-bar quantum-mode";
    info.innerHTML    = `N = <span>${n}</span> ${sep} <span>${fact}</span> combinations ${sep} QAOA on Amazon Braket SV1 ${sep} <span>${n * n} qubits</span> ${sep} Verified classically ${sep} Async result`;
  }
}

function updateChips(n) {
  const chips = (names, cls, prefix) =>
    names.map((a) => `<span class="label-chip ${cls}">${prefix}${escapeHtml(a)}</span>`).join("");
  $("analyst-chips").innerHTML = '<span class="chips-label">Analysts</span>' + chips(ANALYST_NAMES[n], "analyst", "");
  $("alert-chips").innerHTML   = '<span class="chips-label">Threats</span>'  + chips(ALERT_NAMES[n], "alert", "⚠ ");
}

function buildTable(n) {
  const analysts = ANALYST_NAMES[n];
  const alerts   = ALERT_NAMES[n];
  let html = "<tr><th></th>";
  alerts.forEach((a) => {
    html += `<th class="col-header" title="${escapeHtml(a)}">⚠ ${escapeHtml(a)}</th>`;
  });
  html += "</tr>";
  analysts.forEach((analyst, i) => {
    html += `<tr><td class="row-header">${escapeHtml(analyst)}</td>`;
    alerts.forEach((alert, j) => {
      html += `<td><input type="text" inputmode="numeric" id="c${i}_${j}" placeholder="—"
        autocomplete="off" aria-label="${escapeHtml(analyst)} on ${escapeHtml(alert)} (USD)"/></td>`;
    });
    html += "</tr>";
  });
  $("cost-table").innerHTML = html;
}

// Cell input: digits only, max 6 digits ($999,999). Delegated to the table.
function onCellInput(event) {
  const el = event.target;
  if (el.tagName !== "INPUT") return;
  el.value = el.value.replace(/\D/g, "").slice(0, 6);
}

function generateValues() {
  const n = getN();
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const el = $(`c${i}_${j}`);
      if (!el.value) el.value = randCost();
    }
  }
}

function clearTable() {
  const n = getN();
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) $(`c${i}_${j}`).value = "";
  }
  resetResult();
}

function readMatrix() {
  const n = getN();
  const matrix = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      const v = parseInt($(`c${i}_${j}`).value, 10);
      if (Number.isNaN(v) || v < 0) return null;
      row.push(v);
    }
    matrix.push(row);
  }
  return matrix;
}

// ── API ─────────────────────────────────────────────────────────────────────
async function submitJob() {
  const n = getN();
  const matrix = readMatrix();
  if (!matrix) {
    showError("All cells must be filled before running the optimizer. Use Generate Random Values.");
    return;
  }
  const payload = { analysts: ANALYST_NAMES[n], alerts: ALERT_NAMES[n], cost_matrix: matrix };

  setSubmitting(true);
  resetResult();
  try {
    const resp = await fetch(`${API_URL}/optimize`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = await resp.json().catch(() => ({}));

    if (resp.status === 202 && data.status === "PENDING") {
      showQuantumStatus(data);
      startPolling(data.job_id);
    } else if (resp.ok) {
      setSubmitting(false);
      showResult(data);
    } else if (resp.status === 429) {
      setSubmitting(false);
      showError(data.error || "Too many requests. Please wait a moment and try again.");
    } else {
      setSubmitting(false);
      showError(data.error || `Unexpected error from optimizer (HTTP ${resp.status}).`);
    }
  } catch (e) {
    setSubmitting(false);
    showError(`Network error: ${e.message}`);
  }
}

function startPolling(jobId) {
  stopPolling();
  const started = Date.now();

  const poll = async () => {
    if (Date.now() - started > POLL_TIMEOUT_MS) {
      finishQuantum();
      showError(`The quantum job is taking longer than expected. Job ID: ${jobId}`);
      return;
    }
    try {
      const resp = await fetch(`${API_URL}/jobs/${encodeURIComponent(jobId)}`);
      const data = await resp.json().catch(() => ({}));
      if (data.status === "COMPLETE") {
        finishQuantum();
        showResult(data);
        return;
      }
      if (data.status === "FAILED" || resp.status === 404 || resp.status === 400) {
        finishQuantum();
        showError(data.error || "The quantum job failed.");
        return;
      }
      if (data.message) $("qs-info").textContent = `Job ${jobId} · ${data.message}`;
    } catch (_) {
      // transient network error: keep polling until the timeout
    }
    pollTimer = setTimeout(poll, POLL_INTERVAL_MS);
  };
  pollTimer = setTimeout(poll, POLL_INTERVAL_MS);
}

function stopPolling() {
  clearTimeout(pollTimer);
  pollTimer = null;
}

function finishQuantum() {
  stopPolling();
  hideQuantumStatus();
  setSubmitting(false);
}

// ── Rendering ───────────────────────────────────────────────────────────────
function showQuantumStatus(data) {
  $("quantum-status").className = "show";
  $("qs-info").textContent =
    `Job ${data.job_id} · ${data.qubits} qubits · ${Number(data.shots).toLocaleString("en-US")} shots · Amazon Braket SV1`;
}

function hideQuantumStatus() {
  $("quantum-status").className = "";
}

function renderQaoa(q) {
  if (!q) return "";
  let verdict;
  if (q.qaoa_cost === null || q.qaoa_cost === undefined) {
    verdict = "None of the sampled bitstrings encoded a valid assignment.";
  } else if (q.qaoa_found_optimum) {
    verdict = "The best valid sample <strong>matched the proven optimum</strong>.";
  } else {
    verdict = `The best valid sample was <strong>${escapeHtml(q.qaoa_gap_pct)}%</strong> above the optimum.`;
  }
  const metric = (label, value) =>
    `<div class="qaoa-metric"><span class="label">${label}</span><span class="value">${value}</span></div>`;

  return `
    <div class="qaoa-panel">
      <h3>⚛ QAOA on Amazon Braket SV1 · ${escapeHtml(q.qubits)} qubits · p = ${escapeHtml(q.layers)}</h3>
      <div class="qaoa-grid">
        ${metric("Shots", Number(q.shots).toLocaleString("en-US"))}
        ${metric("Valid assignments", formatPct(q.feasible_fraction))}
        ${metric("Optimal samples", formatPct(q.optimal_fraction, 2))}
        ${metric("Best sampled cost", formatUSD(q.qaoa_cost))}
      </div>
      <p class="qaoa-note">${verdict} The recommendation above is the exact optimum, confirmed by checking every possible assignment classically.</p>
    </div>`;
}

function showResult(data) {
  const isQuantum = data.method === "QUANTUM";
  const cls = isQuantum ? "quantum" : "classical";
  const methodLabel = isQuantum
    ? "⚛ Hybrid Result — QAOA + Classical Verification"
    : "✅ Brute-Force — Global Optimum Found";

  const pairsHtml = (data.assignment || []).map((p) => `
    <div class="pair-card ${cls}">
      <div class="pair-names">${escapeHtml(p.analyst)}<span class="pair-arrow">→</span>⚠ ${escapeHtml(p.alert)}</div>
      <div class="pair-cost">${formatUSD(p.cost)} breach impact</div>
    </div>`).join("");

  const savings = Number(data.savings);
  const meta = `
    <div class="result-meta">
      <span>Greedy baseline: <strong>${formatUSD(data.greedy_cost)}</strong></span>
      <span class="saving">Saved vs greedy: <strong>${formatUSD(savings)}</strong></span>
      <span>Assignments checked: <strong>${Number(data.combinations_evaluated).toLocaleString("en-US")}</strong></span>
    </div>`;

  const source = data.narrative_source === "bedrock"
    ? "Summary generated by Claude on Amazon Bedrock"
    : "Summary generated from a template (Bedrock unavailable)";

  const panel = $("result-panel");
  panel.className = "show";
  panel.innerHTML = `
    <div class="result-header"><h2>${methodLabel}</h2></div>
    <div class="result-cost">
      <span class="cost-label">Total Financial Exposure</span>
      ${formatUSD(data.total_cost)}
    </div>
    ${meta}
    ${isQuantum ? renderQaoa(data.qaoa) : ""}
    <div class="result-grid">${pairsHtml}</div>
    <div class="narrative">${escapeHtml(data.narrative)}<span class="narrative-source">${source}</span></div>`;
}

function showError(msg) {
  const panel = $("result-panel");
  panel.className = "show";
  panel.innerHTML = `<div class="error-box">⚠ ${escapeHtml(msg)}</div>`;
}

function setSubmitting(on) {
  ["btn-submit", "btn-generate", "btn-clear", "size-select"].forEach((id) => {
    $(id).disabled = on;
  });
  $("btn-submit").innerHTML = on
    ? '<span class="spinner inline"></span> Optimizing…'
    : "▶ Find Optimal Assignment";
}

function resetResult() {
  stopPolling();
  hideQuantumStatus();
  const p = $("result-panel");
  p.className = "";
  p.innerHTML = "";
}

// ── Wiring ──────────────────────────────────────────────────────────────────
$("size-select").addEventListener("change", onSizeChange);
$("btn-generate").addEventListener("click", generateValues);
$("btn-clear").addEventListener("click", clearTable);
$("btn-submit").addEventListener("click", submitJob);
$("cost-table").addEventListener("input", onCellInput);

onSizeChange();
